import java.util.*;
import java.lang.*;
import java.io.*;

class Codechef
{
    static DataInputStream in = new DataInputStream(new BufferedInputStream(System.in,1<<16));
    static long nextLong() throws IOException{
        int b=in.read();
        while(b<'0')b=in.read();
        long r=0;
        while(b>='0'){
            r=r*10+(b-'0');
            b=in.read();
        }
        return r;
        
    }
    static long[]P;
    static int N3;
    static long f(int i,int b){
        return P[i+2*b]+3L*P[N3-2*i-b];
    }
	public static void main (String[] args) throws java.lang.Exception
	{
	  int t=(int) nextLong();
	  StringBuilder sb =new StringBuilder();
	  Random rnd = new Random(System.nanoTime());
	  while(t-->0){
	      int n=(int) nextLong();
	      int len =3*n;
	      N3=len;
	      long[] s= new long[len];
	      for(int i=0;i<len;i++) s[i]=nextLong();
	      for(int i=len-1;i>0;i--){
	          int j=rnd.nextInt(i+1);
	          long tmp =s[i]; s[i]=s[j]; s[j]=tmp;
	      }
	      Arrays.sort(s);
	      P=new long[len+1];
	      for(int i=0;i<len;i++){
	          P[i+1]=P[i]+s[len-1-i];
	          
	      }
	      long best=0;
	      for(int i=0;i<=n;i++){
	          int m=n-i;
	          int lo=0,hi=m;
	          while(lo<hi){
	              int mid =(lo+hi)>>>1;
	              if(f(i,mid+1)>f(i,mid)) lo=mid+1;
	              else hi=mid;
	          }
	          long val=2L*P[i]+f(i,lo);
	          if(val>best)best=val;
	      }
	      sb.append(best).append("\n");
	  }
	  System.out.print(sb);
	  	}
}
